push!(LOAD_PATH, @__DIR__)
using FloatAbstractions
using SoftFloats: SoftFloat


function check_selbtz_two_sum_lemmas(
    value_map::Dict{SELBTZAbstraction,Vector{T}},
) where {T}

    ± = false:true
    p = precision(T)
    pos_zero = SELBTZAbstraction(zero(T))
    neg_zero = SELBTZAbstraction(-zero(T))
    abstract_inputs = sort!(collect(keys(value_map)))
    lemma_counts = Dict{String,Int}()

    for x in abstract_inputs, y in abstract_inputs

        sx, lbx, ex, fx, gx = unpack(x, T)
        sy, lby, ey, fy, gy = unpack(y, T)
        same_sign = (sx == sy)
        diff_sign = (sx != sy)
        x_zero = (x == pos_zero) | (x == neg_zero)
        y_zero = (y == pos_zero) | (y == neg_zero)
        checker = LemmaChecker(
            two_sum_abstractions(value_map, x, y), x, y, T, lemma_counts)

        #! format: off
        if x_zero | y_zero ###################################### LEMMA FAMILY Z

            checker("SELBTZ-TwoSum-Z1-P", x_zero & y_zero & !(sx & sy)) do lemma
                add_case!(lemma, pos_zero, pos_zero)
            end
            checker("SELBTZ-TwoSum-Z1-N", x_zero & y_zero & sx & sy) do lemma
                add_case!(lemma, neg_zero, pos_zero)
            end

            checker("SELBTZ-TwoSum-Z2-X", y_zero & !x_zero) do lemma
                add_case!(lemma, x, pos_zero)
            end
            checker("SELBTZ-TwoSum-Z2-Y", x_zero & !y_zero) do lemma
                add_case!(lemma, y, pos_zero)
            end

        else ############################################ NONZERO LEMMA FAMILIES

            ##################################################### LEMMA FAMILY I

            checker("SELBTZ-TwoSum-I-X",
                (ex > ey + (p+1)) |
                (!lby & (ex == ey + p) & (ey == gy) & (ex < gx + (p-1)) & (same_sign | (ex > gx))) |
                ((ex == ey + (p+1)) & (same_sign | (ex > gx) | (!lby & (ey == gy))))
            ) do lemma
                add_case!(lemma, x, y)
            end
            checker("SELBTZ-TwoSum-I-Y",
                (ey > ex + (p+1)) |
                (!lbx & (ey == ex + p) & (ex == gx) & (ey < gy + (p-1)) & (same_sign | (ey > gy))) |
                ((ey == ex + (p+1)) & (same_sign | (ey > gy) | (!lbx & (ex == gx))))
            ) do lemma
                add_case!(lemma, y, x)
            end

            ########################################### FAMILY L - CODIMENSION 0

            checker("SELBTZ-TwoSum-La-X",
                (same_sign != lbx) &
                (ex > ey + 1) & (gx < gy) &
                ((fx < fy) | (fx < gy) | (!lby & (fx + 1 < ey)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-La-Y",
                (same_sign != lby) &
                (ey > ex + 1) & (gy < gx) &
                ((fy < fx) | (fy < gx) | (!lbx & (fy + 1 < ex)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-Lb-X",
                (same_sign != lbx) &
                (ex > ey + 2) & (fx < ey + 1) & (fx > fy) & (gx < gy) &
                (lby | (fx == ey))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey+1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-Lb-Y",
                (same_sign != lby) &
                (ey > ex + 2) & (fy < ex + 1) & (fy > fx) & (gy < gx) &
                (lbx | (fy == ex))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex+1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-Lc-X",
                same_sign & lbx &
                (ex + 1 > ey) & (fx + 1 > fy) & (gx < gy) &
                (ex < gx + (p-1)) &
                (
                    (!lby & (fx + 1 < ey) & ((fy == gy) | (fx > fy))) |
                    (lby & (fx + 1 == ey) & (fx == gy) & (gy == fy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-Lc-Y",
                same_sign & lby &
                (ey + 1 > ex) & (fy + 1 > fx) & (gy < gx) &
                (ey < gy + (p-1)) &
                (
                    (!lbx & (fy + 1 < ex) & ((fx == gx) | (fy > fx))) |
                    (lbx & (fy + 1 == ex) & (fy == gx) & (gx == fx + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-Ld-X",
                same_sign & lbx &
                (ex > ey) & (fx + 1 < ey) & (gx < gy) &
                (ex < gx + (p-1)) &
                (lby | (fx < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-Ld-Y",
                same_sign & lby &
                (ey > ex) & (fy + 1 < ex) & (gy < gx) &
                (ey < gy + (p-1)) &
                (lbx | (fy < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-Le-X",
                diff_sign & !lbx &
                (ex > ey + 1) & (gx < gy) &
                (
                    (!lby & (fx + 1 < ey) & ((fx > fy) | ((fx == fy) & (fx == gy)))) |
                    (lby & (fx + 1 == ey) & (fx == gy) & (fy + 1 == gy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey-1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-Le-Y",
                diff_sign & !lby &
                (ey > ex + 1) & (gy < gx) &
                (
                    (!lbx & (fy + 1 < ex) & ((fy > fx) | ((fy == fx) & (fy == gx)))) |
                    (lbx & (fy + 1 == ex) & (fy == gx) & (fx + 1 == gx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-Lf-X",
                diff_sign & !lbx &
                (ex > ey + 2) & (fx + 1 < ey) & (gx < gy) &
                (lby | (fx < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-Lf-Y",
                diff_sign & !lby &
                (ey > ex + 2) & (fy + 1 < ex) & (gy < gx) &
                (lbx | (fy < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gy), pos_zero)
            end

            ########################################### FAMILY L - CODIMENSION 1

            checker("SELBTZ-TwoSum-LA0-X",
                (same_sign != lbx) &
                (gx == gy) &
                (ex > ey + 1) &
                (
                    (!lby & (fx == fy) & (fx > gx)) |
                    (lby & (fx < fy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gy+1:fy), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA0-Y",
                (same_sign != lby) &
                (gy == gx) &
                (ey > ex + 1) &
                (
                    (!lbx & (fy == fx) & (fy > gy)) |
                    (lbx & (fy < fx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gx+1:fx), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA1-X",
                (same_sign != lbx) &
                (gx == gy) &
                (ex > ey + 2) & (fx > gx) & (fx < ey + 1) & (fx > fy) &
                (lby | (fx == ey))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey+1, gy+1:fx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA1-Y",
                (same_sign != lby) &
                (gy == gx) &
                (ey > ex + 2) & (fy > gy) & (fy < ex + 1) & (fy > fx) &
                (lbx | (fy == ex))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex+1, gx+1:fy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA2-X",
                (same_sign != lbx) & !lby &
                (gx == gy) &
                (ex > ey + 1) & (fx + 1 < ey) &
                ((fx > fy) | (same_sign & !lbx & (gx == fy)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gx+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, fx+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA2-Y",
                (same_sign != lby) & !lbx &
                (gy == gx) &
                (ey > ex + 1) & (fy + 1 < ex) &
                ((fy > fx) | (same_sign & !lby & (gy == fx)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gy+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, fy+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA3-X",
                (same_sign != lbx) & !lby &
                (gx == gy) &
                (ex > ey + 1) & (fx < fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gx+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, fy+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA3-Y",
                (same_sign != lby) & !lbx &
                (gy == gx) &
                (ey > ex + 1) & (fy < fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gy+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, fx+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA4-X",
                same_sign & (lbx != lby) &
                (gx == gy) &
                (ex + 1 > ey) & (fx + 1 < ey) & (fx > fy) & (fx > gx) &
                ((lbx & !lby) | (ex == ey))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lby, ex+1, ey-1, gx+1:fx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA4-Y",
                same_sign & (lby != lbx) &
                (gy == gx) &
                (ey + 1 > ex) & (fy + 1 < ex) & (fy > fx) & (fy > gy) &
                ((lby & !lbx) | (ey == ex))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lbx, ey+1, ex-1, gy+1:fy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA5-X",
                same_sign & lbx &
                (gx == gy) &
                (ex > ey) & (fy > gy) &
                (
                    (!lby & (fx < fy)) |
                    (lby & (fx == fy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx+1:fy), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA5-Y",
                same_sign & lby &
                (gy == gx) &
                (ey > ex) & (fx > gx) &
                (
                    (!lbx & (fy < fx)) |
                    (lbx & (fy == fx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy+1:fx), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA6-X",
                diff_sign & !lbx &
                (gx == gy) &
                (ex > ey + 2) &
                (
                    (!lby & (fx < fy)) |
                    (lby & (fx == fy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, gy+1:fy), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA6-Y",
                diff_sign & !lby &
                (gy == gx) &
                (ey > ex + 2) &
                (
                    (!lbx & (fy < fx)) |
                    (lbx & (fy == fx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gx+1:fx), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA7-X",
                same_sign & lbx & lby &
                (gx == gy) &
                (ex > ey) & (fx + 1 < ey) & (fx > fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gy+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, fx+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA7-Y",
                same_sign & lby & lbx &
                (gy == gx) &
                (ey > ex) & (fy + 1 < ex) & (fy > fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gx+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, fy+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA8-X",
                same_sign & lbx & lby &
                (gx == gy) &
                (ex > ey) & (fx < fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, fy+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA8-Y",
                same_sign & lby & lbx &
                (gy == gx) &
                (ey > ex) & (fy < fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, fx+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA9-X",
                diff_sign & !lbx & !lby &
                (gx == gy) &
                (ex > ey + 1) & (fx + 1 < ey) & (fx > fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey-1, gx+1:fx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA9-Y",
                diff_sign & !lby & !lbx &
                (gy == gx) &
                (ey > ex + 1) & (fy + 1 < ex) & (fy > fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, gy+1:fy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA10-X",
                diff_sign & !lbx & lby &
                (gx == gy) &
                (ex > ey + 2) & (fx + 1 < ey) & (fx > fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, gx+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, fx+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA10-Y",
                diff_sign & !lby & lbx &
                (gy == gx) &
                (ey > ex + 2) & (fy + 1 < ex) & (fy > fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gy+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, fy+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LA11-X",
                diff_sign & !lbx & lby &
                (gx == gy) &
                (ex > ey + 2) & (fx < fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, gx+1:fy-1), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, fy+1), pos_zero)
            end
            checker("SELBTZ-TwoSum-LA11-Y",
                diff_sign & !lby & lbx &
                (gy == gx) &
                (ey > ex + 2) & (fy < fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gy+1:fx-1), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, fx+1), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB0-X",
                (same_sign != lbx) &
                (ex == ey + 1) &
                (gx < gy) &
                (
                    (!lby & (ex == fy + 3) & (fx == gy) & (fy == gy + 1)) |
                    (lby & (fx < fy) & (fx < gy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ~lbx, ex, fy, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB0-Y",
                (same_sign != lby) &
                (ey == ex + 1) &
                (gy < gx) &
                (
                    (!lbx & (ey == fx + 3) & (fy == gx) & (fx == gx + 1)) |
                    (lbx & (fy < fx) & (fy < gx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ~lby, ey, fx, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB1-X",
                (same_sign != lbx) & !lby &
                (ex == ey + 1) &
                (fx + 1 < ey) & (gx < gy) &
                ((fx < gy) | ((ex > fx + 3) & (ex > fy + 3)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ~lbx, ex, ex-2, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB1-Y",
                (same_sign != lby) & !lbx &
                (ey == ex + 1) &
                (fy + 1 < ex) & (gy < gx) &
                ((fy < gx) | ((ey > fy + 3) & (ey > fx + 3)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ~lby, ey, ey-2, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB2-X",
                diff_sign & (lbx == lby) &
                (ex == ey + 1) &
                (fx + 1 < ey) & (fx > fy + 1) & (gx < gy) & (ey > gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex-1, fx-1:fx, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB2-Y",
                diff_sign & (lby == lbx) &
                (ey == ex + 1) &
                (fy + 1 < ex) & (fy > fx + 1) & (gy < gx) & (ex > gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey-1, fy-1:fy, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB3-X",
                same_sign & !lbx & lby &
                (ex == ey + 1) &
                (fx > fy + 1) & (gx < gy) &
                (gx + (p-2) > ey)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, fx-1:fx, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB3-Y",
                same_sign & !lby & lbx &
                (ey == ex + 1) &
                (fy > fx + 1) & (gy < gx) &
                (gy + (p-2) > ex)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, fy-1:fy, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB4-X",
                diff_sign & !lbx & !lby &
                (ex == ey + 1) &
                (fx + 1 < fy) & (fx + 1 > gy) & (gx < gy) & (ey > fy + 2)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-2, fy-1:fy, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB4-Y",
                diff_sign & !lby & !lbx &
                (ey == ex + 1) &
                (fy + 1 < fx) & (fy + 1 > gx) & (gy < gx) & (ex > fx + 2)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-2, fx-1:fx, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB5-X",
                diff_sign & !lbx & lby &
                (ex == ey + 1) &
                (fx < fy) & (fx > gy) & (gx < gy) & (gy + 2 < fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, fy+1, gx:fx, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 0, fy, fx:fy-2, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, fy, gx-1, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, fy, gx+1:fy-2, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB5-Y",
                diff_sign & !lby & lbx &
                (ey == ex + 1) &
                (fy < fx) & (fy > gx) & (gy < gx) & (gx + 2 < fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, fx+1, gy:fy, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 0, fx, fy:fx-2, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, fx, gy-1, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, fx, gy+1:fx-2, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LB6-X",
                diff_sign & !lbx & lby &
                (ex == ey + 1) &
                (fx > fy) & (fx > gy + 2) & (gx < gy) & (gy < fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, fx+1, gx:fy, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 0, fx, fy:fx-2, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, fx, gx-1, gx), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, fx, gx+1:fx-2, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-LB6-Y",
                diff_sign & !lby & lbx &
                (ey == ex + 1) &
                (fy > fx) & (fy > gx + 2) & (gy < gx) & (gx < fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, fy+1, gy:fx, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 0, fy, fx:fy-2, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, fy, gy-1, gy), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, fy, gy+1:fy-2, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-LC0-X",
                same_sign & (lbx == lby) &
                (ex == ey) &
                (fx < fy) & (fx + 1 > gy) & (gx < gy) & (gy + 1 < fy) &
                (ex < gx + (p-1))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex+1, fy:fy+1, gx), pos_zero)
