                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, fx), SELBTZRange(sx, gx:ey-(p+2), gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, ex), SELBTZRange(~sx, gx:ey-(p+2), gx))
            end

            checker("SELBTZ-TwoSum-3LQ2-X",
                diff_sign & lbx &
                (ex > ey + 2) &
                (ex > gy + p) &
                (
                    (!lby & (fx + 1 == ey) & (gx + 2 == ey) & (gx == fy)) |
                    (lby & (fx == fy) & (fx + 1 == gx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, ey+1, ex-(p-1):fy), SELBTZRange(~sy, gy:ex-(p+1), gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, ey+1, ex-(p-1):fy-1), SELBTZRange(sy, gy:ex-(p+1), gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, ey, ey+1), SELBTZRange(sy, gy:ex-(p+1), gy))
            end
            checker("SELBTZ-TwoSum-3LQ2-Y",
                diff_sign & lby &
                (ey > ex + 2) &
                (ey > gx + p) &
                (
                    (!lbx & (fy + 1 == ex) & (gy + 2 == ex) & (gy == fx)) |
                    (lbx & (fy == fx) & (fy + 1 == gy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, ex+1, ey-(p-1):fx), SELBTZRange(~sx, gx:ey-(p+1), gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, ex+1, ey-(p-1):fx-1), SELBTZRange(sx, gx:ey-(p+1), gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, ex, ex+1), SELBTZRange(sx, gx:ey-(p+1), gx))
            end

            checker("SELBTZ-TwoSum-3CPS0-X",
                diff_sign & !lbx & !lby &
                (fx == ey) & (gx == ey) &
                (ex < fy + (p+1)) & (ex > gy + (p+1))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, fy, ex-p:fy-1), SELBTZRange(±, gy:ex-(p+2), gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, fy, fy+1), SELBTZRange(~sy, gy:ex-(p+2), gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, fy-1, fy), SELBTZRange(sy, gy:ex-(p+2), gy))
            end
            checker("SELBTZ-TwoSum-3CPS0-Y",
                diff_sign & !lby & !lbx &
                (fy == ex) & (gy == ex) &
                (ey < fx + (p+1)) & (ey > gx + (p+1))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, fx, ey-p:fx-1), SELBTZRange(±, gx:ey-(p+2), gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, fx, fx+1), SELBTZRange(~sx, gx:ey-(p+2), gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, fx-1, fx), SELBTZRange(sx, gx:ey-(p+2), gx))
            end

            checker("SELBTZ-TwoSum-3CPS1-X",
                diff_sign & !lbx & !lby &
                (fx == gx) & (gx == ey) &
                (fy > gy) &
                (ex > fy + (p+1))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ex, ex), SELBTZRange(sy, fy, gy))
            end
            checker("SELBTZ-TwoSum-3CPS1-Y",
                diff_sign & !lby & !lbx &
                (fy == gy) & (gy == ex) &
                (fx > gx) &
                (ey > fx + (p+1))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ey, ey), SELBTZRange(sx, fx, gx))
            end

            checker("SELBTZ-TwoSum-3GLR0-X",
                same_sign & lbx & !lby &
                (ex == gx + (p-1)) & (gx == fy + 2) &
                (fx + 1 < ey) & (fx > gx) & (fy > gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, gx+1:fx), SELBTZRange(~sy, 0, gx-1, gy:gx-3, gy))
            end
            checker("SELBTZ-TwoSum-3GLR0-Y",
                same_sign & lby & !lbx &
                (ey == gy + (p-1)) & (gy == fx + 2) &
                (fy + 1 < ex) & (fy > gy) & (fx > gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, gy+1:fy), SELBTZRange(~sx, 0, gy-1, gx:gy-3, gx))
            end

            checker("SELBTZ-TwoSum-3GLR1-X",
                same_sign & lbx & lby &
                (ex == gx + (p-1)) & (gx == fy + 2) &
                (fx < ey) & (fx > gx) & (fy > gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx+1:fx-1), SELBTZRange(sy, 0, gx-1, gy:gx-3, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, fx+1), SELBTZRange(sy, 0, gx-1, gy:gx-3, gy))
            end
            checker("SELBTZ-TwoSum-3GLR1-Y",
                same_sign & lby & lbx &
                (ey == gy + (p-1)) & (gy == fx + 2) &
                (fy < ex) & (fy > gy) & (fx > gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy+1:fy-1), SELBTZRange(sx, 0, gy-1, gx:gy-3, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, fy+1), SELBTZRange(sx, 0, gy-1, gx:gy-3, gx))
            end

            checker("SELBTZ-TwoSum-3GLR2-X",
                same_sign & lbx & lby &
                (ex > ey) & (fx < ey) & (fx > gx) & (gx > gy) &
                ((ex == gx + (p-2)) | (ex == gx + (p-1))) &
                ((gx == fy + 1) | ((gx == gy + 1) & (fy + 1 == gy)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx+1:fx-1), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, fx+1), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx+1:fx-1), SELBTZRange(sy, gy+1:fy-1, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, fx+1), SELBTZRange(sy, gy+1:fy-1, gy))
            end
            checker("SELBTZ-TwoSum-3GLR2-Y",
                same_sign & lby & lbx &
                (ey > ex) & (fy < ex) & (fy > gy) & (gy > gx) &
                ((ey == gy + (p-2)) | (ey == gy + (p-1))) &
                ((gy == fx + 1) | ((gy == gx + 1) & (fx + 1 == gx)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy+1:fy-1), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, fy+1), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy+1:fy-1), SELBTZRange(sx, gx+1:fx-1, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, fy+1), SELBTZRange(sx, gx+1:fx-1, gx))
            end

            ########################################### FAMILY 3 - CODIMENSION 3

            checker("SELBTZ-TwoSum-3P-X",
                same_sign &
                (gx == ey + 1) &
                (
                    (!lbx & lby & (ex == gx) & (ex == fx + p) & (ex == gy + p) & (fy + 1 == gy)) |
                    (lbx & !lby & (ex == gy + p) & (fx == ey) & (ey == gy) & (ey == fy + p)) |
                    (lbx & lby & (fx == ey) & (fy + 1 == gy) & (ex > gy + (p-1)))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ex+1, ex+1), SELBTZRange(~sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3P-Y",
                same_sign &
                (gy == ex + 1) &
                (
                    (!lby & lbx & (ey == gy) & (ey == fy + p) & (ey == gx + p) & (fx + 1 == gx)) |
                    (lby & !lbx & (ey == gx + p) & (fy == ex) & (ex == gx) & (ex == fx + p)) |
                    (lby & lbx & (fy == ex) & (fx + 1 == gx) & (ey > gx + (p-1)))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ey+1, ey+1), SELBTZRange(~sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3AL1-X",
                same_sign & lby &
                (gx > gy) &
                ((ex == gy + (p-1)) | (ex == gy + p)) &
                ((gx == fy + 1) | ((gx == gy + 1) & (fy + 1 == gy))) &
                (
                    (!lbx & (ex == ey + 1) & (fx == gx)) |
                    (lbx & (fx == ey))
                )
            ) do lemma
                for gs = gx+1:fx-1
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, gs:fx-1, gs), SELBTZRange(sy, gy, gy))
                end
                add_case!(lemma, SELBTZRange(sx, ex+1, ex+1), SELBTZRange(sy, gy, gy))
                for gs = gy+2:fy
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, gs:fy-1, gs), SELBTZRange(sy, gy, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, gs, gs), SELBTZRange(~sy, gy, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, gs+1:fy-1, gs), SELBTZRange(~sy, gy, gy))
                end
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, gx+1:fx-1, gy+2:fy), SELBTZRange(~sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, gx+1:fx-1, gy+2:fy-1), SELBTZRange(sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3AL1-Y",
                same_sign & lbx &
                (gy > gx) &
                ((ey == gx + (p-1)) | (ey == gx + p)) &
                ((gy == fx + 1) | ((gy == gx + 1) & (fx + 1 == gx))) &
                (
                    (!lby & (ey == ex + 1) & (fy == gy)) |
                    (lby & (fy == ex))
                )
            ) do lemma
                for gs = gy+1:fy-1
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, gs:fy-1, gs), SELBTZRange(sx, gx, gx))
                end
                add_case!(lemma, SELBTZRange(sy, ey+1, ey+1), SELBTZRange(sx, gx, gx))
                for gs = gx+2:fx
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, gs:fx-1, gs), SELBTZRange(sx, gx, gx))
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, gs, gs), SELBTZRange(~sx, gx, gx))
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, gs+1:fx-1, gs), SELBTZRange(~sx, gx, gx))
                end
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, gy+1:fy-1, gx+2:fx), SELBTZRange(~sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, gy+1:fy-1, gx+2:fx-1), SELBTZRange(sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3AP-X",
                same_sign & !lby &
                (ex == gy + (p-1)) & (gx == ey) &
                (fy > gy) & ((lbx & (fx + 1 == ey)) | (!lbx & (ex == gx) & (ex == fx + p)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, fy, gy+2:fy), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, fy, gy+2:fy-1), SELBTZRange(~sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, fy+1, fy+1), SELBTZRange(~sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3AP-Y",
                same_sign & !lbx &
                (ey == gx + (p-1)) & (gy == ex) &
                (fx > gx) & ((lby & (fy + 1 == ex)) | (!lby & (ey == gy) & (ey == fy + p)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, fx, gx+2:fx), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, fx, gx+2:fx-1), SELBTZRange(~sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, fx+1, fx+1), SELBTZRange(~sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3CJ3-X",
                diff_sign & lbx &
                (fx == ey) & (gx == ey + 1) &
                (
                    (!lby & (ex == ey + p) & (fx == gy) & (ey == fy + p)) |
                    (lby & (fy + 1 == gy) & (ex > ey + 2) & (ex > fy + p))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, gx, gx+1), SELBTZRange(~sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3CJ3-Y",
                diff_sign & lby &
                (fy == ex) & (gy == ex + 1) &
                (
                    (!lbx & (ey == ex + p) & (fy == gx) & (ex == fx + p)) |
                    (lbx & (fx + 1 == gx) & (ey > ex + 2) & (ey > fx + p))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, gy, gy+1), SELBTZRange(~sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3EP-X",
                same_sign &
                (ex == gy + p) &
                (fy > gy + 1) &
                (
                    (!lbx & !lby & (ex == ey + 1) & (ex == fx + 3) & (fx == fy) & (gx == fy)) |
                    (lby & (gx == ey + 1) & ((lbx & (fx == ey)) | (!lbx & (ex == gx) & (ex == fx + p))))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, gy+2:fy-1), SELBTZRange(±, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fy+1), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy-1, fy), SELBTZRange(~sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3EP-Y",
                same_sign &
                (ey == gx + p) &
                (fx > gx + 1) &
                (
                    (!lby & !lbx & (ey == ex + 1) & (ey == fy + 3) & (fy == fx) & (gy == fx)) |
                    (lbx & (gy == ex + 1) & ((lby & (fy == ex)) | (!lby & (ey == gy) & (ey == fy + p))))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, gx+2:fx-1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fx+1), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx-1, fx), SELBTZRange(~sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3GU-X",
                same_sign & lbx & !lby &
                (ex == gx + (p-1)) & (ey == gy) & (ey == fy + p) &
                (ex + 1 > ey) & (fx > gx) & (fx + 1 < ey)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, gx+2:fx), SELBTZRange(~sy, gx, gx))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, gx+2:fx-1), SELBTZRange(sy, gx, gx))
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, fx+1), SELBTZRange(sy, gx, gx))
            end
            checker("SELBTZ-TwoSum-3GU-Y",
                same_sign & lby & !lbx &
                (ey == gy + (p-1)) & (ex == gx) & (ex == fx + p) &
                (ey + 1 > ex) & (fy > gy) & (fy + 1 < ex)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, gy+2:fy), SELBTZRange(~sx, gy, gy))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, gy+2:fy-1), SELBTZRange(sx, gy, gy))
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, fy+1), SELBTZRange(sx, gy, gy))
            end

            checker("SELBTZ-TwoSum-3HP-X",
                same_sign &
                (gx == ey) &
                (
                    (lbx & lby & (fx + 1 == gx) & (ey == gy + 1) & (gy == fy + 1) & ((ex == gy + (p-1)) | (ex == gy + p))) |
                    (lbx & !lby & (fx + 1 == gx) & (fy == gy) & (ex > gy + (p-2))) |
                    (!lbx & !lby & (ex == gx) & (ex == fx + p) & (ex == gy + (p-1)) & (fy == gy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ex+1, ex+1), SELBTZRange(sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3HP-Y",
                same_sign &
                (gy == ex) &
                (
                    (lby & lbx & (fy + 1 == gy) & (ex == gx + 1) & (gx == fx + 1) & ((ey == gx + (p-1)) | (ey == gx + p))) |
                    (lby & !lbx & (fy + 1 == gy) & (fx == gx) & (ey > gx + (p-2))) |
                    (!lby & !lbx & (ey == gy) & (ey == fy + p) & (ey == gx + (p-1)) & (fx == gx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ey+1, ey+1), SELBTZRange(sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3HS-X",
                (same_sign != lbx) &
                (ex > ey + 1) &
                (
                    (diff_sign & lbx & !lby & (fx + 1 == gx) & (gx == ey) & (fy == gy) & (ex > gy + (p-1))) |
                    (lby & (ex == gy + p) & (gx == gy + 1) & (gy == fy + 1) &
                        ((diff_sign & lbx & (fx + 1 == gx)) | (same_sign & !lbx & (ex == ey + 2) & (fx == gx))))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, ey, ey+1), SELBTZRange(sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-3HS-Y",
                (same_sign != lby) &
                (ey > ex + 1) &
                (
                    (diff_sign & lby & !lbx & (fy + 1 == gy) & (gy == ex) & (fx == gx) & (ey > gx + (p-1))) |
                    (lbx & (ey == gx + p) & (gy == gx + 1) & (gx == fx + 1) &
                        ((diff_sign & lby & (fy + 1 == gy)) | (same_sign & !lby & (ey == ex + 2) & (fy == gy))))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, ex, ex+1), SELBTZRange(sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-3PR-X",
                same_sign & lby &
                (gx == ey + 1) &
                (
                    (lbx & (fx == ey) & (((ex == fy + p) & (fy > gy)) | ((ex == gy + p) & (fy == gy + 1)))) |
                    (!lbx & (ex == gx) & (ex == fx + p) & (fx == gy) & (fy == gy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fy+1), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fy+1), SELBTZRange(sy, gy+1:ex-(p+1), gy))
            end
            checker("SELBTZ-TwoSum-3PR-Y",
                same_sign & lbx &
                (gy == ex + 1) &
                (
                    (lby & (fy == ex) & (((ey == fx + p) & (fx > gx)) | ((ey == gx + p) & (fx == gx + 1)))) |
                    (!lby & (ey == gy) & (ey == fy + p) & (fy == gx) & (fx == gx + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fx+1), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fx+1), SELBTZRange(sx, gx+1:ey-(p+1), gx))
            end

            checker("SELBTZ-TwoSum-3ABC-X",
                diff_sign & !lbx & lby &
                (ex == gy + (p+1)) & (fx == ey) & (gx == fy + 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, ex, ex), SELBTZRange(sy, gy, gy))
                for gs = gx+1:fx-1
                    add_case!(lemma, SELBTZRange(sx, 1, ex-1, gs-1, gs), SELBTZRange(sy, gy, gy))
                    add_case!(lemma, SELBTZRange(sx, 1, ex-1, gs+1:fx-1, gs), SELBTZRange(sy, gy, gy))
                end
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, gx+1:fx-1, gy+2:gx-2), SELBTZRange(sy, gy, gy))
                for gs = gy+2:gx-2
                    add_case!(lemma, SELBTZRange(sx, 1, ex-1, gs-1, gs), SELBTZRange(sy, gy, gy))
                    add_case!(lemma, SELBTZRange(sx, 1, ex-1, gs+1:gx-2, gs), SELBTZRange(±, gy, gy))
                end
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, gx+1:fx-1, gy+2:gx-1), SELBTZRange(~sy, gy, gy))
                for gs = gy+2:gx-1
                    add_case!(lemma, SELBTZRange(sx, 1, ex-1, gs-1, gs), SELBTZRange(~sy, gy, gy))
                end
            end
            checker("SELBTZ-TwoSum-3ABC-Y",
                diff_sign & !lby & lbx &
                (ey == gx + (p+1)) & (fy == ex) & (gy == fx + 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, ey, ey), SELBTZRange(sx, gx, gx))
                for gs = gy+1:fy-1
                    add_case!(lemma, SELBTZRange(sy, 1, ey-1, gs-1, gs), SELBTZRange(sx, gx, gx))
