                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fx+1, fx+1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fx+1, gy), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fx:fx+1, gx+2:gy-1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fx, gy), SELBTZRange(~sx, gx, gx))
            end

            ########################################### FAMILY 6 - CODIMENSION 5

            checker("SELBTZ-TwoSum-6ACIV-X",
                same_sign & !lbx & !lby &
                (ex == gx + (p-1)) & (ex + 1 == ey) & (ey == gy) & (ey == fy + p) & (fx == gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex+1, ex-1, ex), SELBTZRange(sy, gx, gx))
            end
            checker("SELBTZ-TwoSum-6ACIV-Y",
                same_sign & !lby & !lbx &
                (ey == gy + (p-1)) & (ey + 1 == ex) & (ex == gx) & (ex == fx + p) & (fy == gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey+1, ey-1, ey), SELBTZRange(sx, gy, gy))
            end

            checker("SELBTZ-TwoSum-6AMOT",
                same_sign & !lbx & !lby &
                (fx == fy) &
                (
                    ((ex == ey + 1) & (ex == fx + 3) & (ex == gy + p) & (fx == gx + 1)) |
                    ((ey == ex + 1) & (ey == fy + 3) & (ey == gx + p) & (fy == gy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, fx+3, fx-1, fx), SELBTZRange(±, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fx+3, fx-1:fx, fx-(p-5):fx-2), SELBTZRange(±, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fx+3, fx, fx-1), SELBTZRange(sy, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fx+3, fx-2, fx-1), SELBTZRange(~sy, fx-(p-3), fx-(p-3)))
            end

            checker("SELBTZ-TwoSum-6CGHI-X",
                same_sign & lbx & lby &
                (ex == ey) & (ex == gx + (p-1)) & (fx + 1 == gx) & (gx + 1 == gy) & (fy + 1 == gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex+1, gy, gx+2), SELBTZRange(sy, gx, gx))
            end
            checker("SELBTZ-TwoSum-6CGHI-Y",
                same_sign & lby & lbx &
                (ey == ex) & (ey == gy + (p-1)) & (fy + 1 == gy) & (gy + 1 == gx) & (fx + 1 == gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey+1, gx, gy+2), SELBTZRange(sx, gy, gy))
            end

            checker("SELBTZ-TwoSum-6GMOT-X",
                same_sign & !lbx & !lby &
                (fx + 1 == fy) &
                (
                    ((ex == ey + 1) & (ex == fy + 3) & (ex == gy + p) & (fx == gx + 1)) |
                    ((ex + 1 == ey) & (ey == fy + 3) & (gx + p == ey) & (fx == gy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, fy+3, fy, fy+1), SELBTZRange(±, fy-(p-3), fy-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fy+3, fy, fy-(p-5):fx), SELBTZRange(±, fy-(p-3), fy-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fy+3, fy+1, fy-(p-5):fx-2), SELBTZRange(±, fy-(p-3), fy-(p-3)))
                add_case!(lemma, SELBTZRange(sx, 1, fy+3, fy+1, fx-1), SELBTZRange(sy, fy-(p-3), fy-(p-3)))
            end
            checker("SELBTZ-TwoSum-6GMOT-Y",
                same_sign & !lby & !lbx &
                (fy + 1 == fx) &
                (
                    ((ey == ex + 1) & (ey == fx + 3) & (ey == gx + p) & (fy == gy + 1)) |
                    ((ey + 1 == ex) & (ex == fx + 3) & (gy + p == ex) & (fy == gx + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, fx+3, fx, fx+1), SELBTZRange(±, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sy, 1, fx+3, fx, fx-(p-5):fy), SELBTZRange(±, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sy, 1, fx+3, fx+1, fx-(p-5):fy-2), SELBTZRange(±, fx-(p-3), fx-(p-3)))
                add_case!(lemma, SELBTZRange(sy, 1, fx+3, fx+1, fy-1), SELBTZRange(sx, fx-(p-3), fx-(p-3)))
            end

            checker("SELBTZ-TwoSum-6ABCEO-X",
                same_sign & !lbx & !lby &
                (ex == fx + 3) & (fx == fy) & (ex == ey + 1) & (ex == gy + p) & (gx == gy + 1)
            ) do lemma
                for gs = gy+2:fx
                    add_case!(lemma, SELBTZRange(sx, 1, ex, gs-1, gs), SELBTZRange(±, gy, gy))
                    add_case!(lemma, SELBTZRange(sx, 1, ex, gs+1:fx, gs), SELBTZRange(±, gy, gy))
                end
            end
            checker("SELBTZ-TwoSum-6ABCEO-Y",
                same_sign & !lby & !lbx &
                (ey == fy + 3) & (fy == fx) & (ey == ex + 1) & (ey == gx + p) & (gy == gx + 1)
            ) do lemma
                for gs = gx+2:fy
                    add_case!(lemma, SELBTZRange(sy, 1, ey, gs-1, gs), SELBTZRange(±, gx, gx))
                    add_case!(lemma, SELBTZRange(sy, 1, ey, gs+1:fy, gs), SELBTZRange(±, gx, gx))
                end
            end

            checker("SELBTZ-TwoSum-6BEFGS-X",
                same_sign & !lbx & !lby &
                (ex == ey + 1) & (ex == fy + 3) & (ex == gy + p) & (fx == gx) & (fx + 1 == fy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fy+1), SELBTZRange(±, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fx), SELBTZRange(~sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy+1, fx), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy:fy+1, gy+2:fx-1), SELBTZRange(±, gy, gy))
            end
            checker("SELBTZ-TwoSum-6BEFGS-Y",
                same_sign & !lby & !lbx &
                (ey == ex + 1) & (ey == fx + 3) & (ey == gx + p) & (fy == gy) & (fy + 1 == fx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fx+1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fy), SELBTZRange(~sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx+1, fy), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx:fx+1, gx+2:fy-1), SELBTZRange(±, gx, gx))
            end

            checker("SELBTZ-TwoSum-6BEIOS-X",
                diff_sign & lbx & !lby &
                (ex == ey + 1) & (ex == gy + p) & (gx == fy) &
                (
                    ((ex == fy + 3) & (fy == fx + 1)) |
                    ((ex == fy + 4) & (fx == fy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-2, ex-2), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-3, gy+2:fy-1), SELBTZRange(±, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-3, fy), SELBTZRange(~sy, gy, gy))
            end
            checker("SELBTZ-TwoSum-6BEIOS-Y",
                diff_sign & lby & !lbx &
                (ey == ex + 1) & (ey == gx + p) & (gy == fx) &
                (
                    ((ey == fx + 3) & (fx == fy + 1)) |
                    ((ey == fx + 4) & (fy == fx + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-2, ey-2), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-3, gx+2:fx-1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-3, fx), SELBTZRange(~sx, gx, gx))
            end

            checker("SELBTZ-TwoSum-6BEOSU-X",
                diff_sign & lbx & !lby &
                (ex == ey + 1) & (ex == gy + p) & (gx + 4 == ey) &
                (
                    ((fx + 3 == ey) & (ey == fy + 2)) |
                    ((fx + 2 == ey) & (ey == fy + 3))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex, ey-1, ey-1), SELBTZRange(±, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ey-1, gy+2:gx-1), SELBTZRange(±, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ey-1, gx), SELBTZRange(sy, gy, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ey-2, gy+2:gx+1), SELBTZRange(±, gy, gy))
            end
            checker("SELBTZ-TwoSum-6BEOSU-Y",
                diff_sign & lby & !lbx &
                (ey == ex + 1) & (ey == gx + p) & (gy + 4 == ex) &
                (
                    ((fy + 3 == ex) & (ex == fx + 2)) |
                    ((fy + 2 == ex) & (ex == fx + 3))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey, ex-1, ex-1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ex-1, gx+2:gy-1), SELBTZRange(±, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ex-1, gy), SELBTZRange(sx, gx, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ex-2, gx+2:gy+1), SELBTZRange(±, gx, gx))
            end

            checker("SELBTZ-TwoSum-6CHJKQ-X",
                same_sign & lbx & !lby &
                (ex == gx + (p-1)) & (ex == ey) & (fx + 1 == gx) & (gx + 1 == gy) & (fy == gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex+1, ex-1, ex), SELBTZRange(sy, gx, gx))
            end
            checker("SELBTZ-TwoSum-6CHJKQ-Y",
                same_sign & lby & !lbx &
                (ey == gy + (p-1)) & (ey == ex) & (fy + 1 == gy) & (gy + 1 == gx) & (fx == gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey+1, ey-1, ey), SELBTZRange(sx, gy, gy))
            end

        end
        #! format: on

        if !isone(length(checker.covering_lemmas))
            error("Abstract SELBTZ-TwoSum-$T inputs ($x, $y) are not covered " *
                "by exactly one lemma.")
        end
    end

    println("SELBTZ-TwoSum-$T lemmas:")
    for (name, n) in sort!(collect(lemma_counts))
        println("    $name: $n")
    end
    flush(stdout)

    return nothing
end


function main_two_sum(::Type{SoftFloat{P}}) where {P}
    value_map = compute_value_map(SELBTZAbstraction, SoftFloat{P}, -2, P)
    check_selbtz_two_sum_lemmas(value_map)
    println("Successfully checked all SELBTZ-TwoSum lemmas at precision $P.")
    flush(stdout)
    return nothing
end


if abspath(PROGRAM_FILE) == @__FILE__
    for P = 7:12
        main_two_sum(SoftFloat{P})
    end
end
